PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,password_iterations INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,plan TEXT NOT NULL DEFAULT 'starter',owner_user_id TEXT NOT NULL,created_at INTEGER NOT NULL,FOREIGN KEY(owner_user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS memberships(organization_id TEXT NOT NULL,user_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('owner','admin','member','viewer')),status TEXT NOT NULL DEFAULT 'active',created_at INTEGER NOT NULL,PRIMARY KEY(organization_id,user_id),FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,last_seen_at INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS sessions_token_idx ON sessions(token_hash);
CREATE TABLE IF NOT EXISTS invites(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,code_hash TEXT NOT NULL UNIQUE,email TEXT,role TEXT NOT NULL DEFAULT 'member',max_uses INTEGER NOT NULL DEFAULT 1,uses INTEGER NOT NULL DEFAULT 0,expires_at INTEGER NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pair_codes(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,user_id TEXT NOT NULL,code_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,used_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,user_id TEXT NOT NULL,name TEXT NOT NULL,platform TEXT NOT NULL,version TEXT NOT NULL,secret_hash TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'active',last_seen_at INTEGER,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS devices_org_idx ON devices(organization_id);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,user_id TEXT NOT NULL,device_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('chat','agent')),input_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',result_json TEXT,error TEXT,lease_expires_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS tasks_device_status_idx ON tasks(device_id,status,created_at);
CREATE TABLE IF NOT EXISTS entitlements(organization_id TEXT NOT NULL,product TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',source TEXT NOT NULL DEFAULT 'operator',expires_at INTEGER,created_at INTEGER NOT NULL,PRIMARY KEY(organization_id,product));
CREATE TABLE IF NOT EXISTS releases(id TEXT PRIMARY KEY,product TEXT NOT NULL,version TEXT NOT NULL,arch TEXT NOT NULL,object_key TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL,bytes INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'published',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS auth_limits(key TEXT PRIMARY KEY,window_start INTEGER NOT NULL,count INTEGER NOT NULL);
